// Minimum window of s containing all chars of t (shortest-cover shape)
string minWindow(const string& s, const string& t) {
    vector<int> need(128, 0);
    for (char c : t) need[c]++;
    int missing = t.size(), l = 0, bestL = 0, bestLen = INT_MAX;
    for (int r = 0; r < (int)s.size(); r++) {
        if (need[s[r]]-- > 0) missing--;           // 1. take s[r]
        while (missing == 0) {                      // 2. window covers t
            if (r - l + 1 < bestLen) bestLen = r - l + 1, bestL = l;  // 3. record
            if (++need[s[l++]] > 0) missing++;     // 4. drop s[l], maybe break cover
        }
    }
    return bestLen == INT_MAX ? "" : s.substr(bestL, bestLen);
}

