long long minimumTime(const vector<int>& time, int totalTrips) {
    auto ok = [&](long long t) {                 // 1. can we finish by time t?
        long long trips = 0;
        for (int x : time) { trips += t / x; if (trips >= totalTrips) return true; }
        return false;
