}

// Basic Calculator III: + - * / and parentheses
long long parse(const string& s, int& i) {
    long long sum = 0, last = 0, num = 0; char op = '+';
    while (i <= (int)s.size()) {
        char c = i < (int)s.size() ? s[i] : '\0';
        if (c == ' ') { i++; continue; }
        if (isdigit(c)) { num = num * 10 + (c - '0'); i++; continue; }
        if (c == '(') { i++; num = parse(s, i); continue; }       // callee eats ')'
        // operator, ')' or end: apply the pending op to num
        if (op == '+') { sum += last; last = num; }
        else if (op == '-') { sum += last; last = -num; }
        else if (op == '*') last *= num; else last /= num;
        num = 0; op = c; i++;
        if (c == ')' || c == '\0') return sum + last;
    }
    return sum + last;
}

