int sumSubarrayMins(const vector<int>& a) {
    int n = a.size(); const int MOD = 1e9 + 7;
    vector<int> L(n), R(n); stack<int> st;
    for (int i = 0; i < n; i++) {                       // L: prev strictly less
        while (!st.empty() && a[st.top()] >= a[i]) st.pop();
        L[i] = st.empty() ? -1 : st.top(); st.push(i);
    }
    st = stack<int>();
    for (int i = n - 1; i >= 0; i--) {                  // R: next less or equal
        while (!st.empty() && a[st.top()] > a[i]) st.pop();
        R[i] = st.empty() ? n : st.top(); st.push(i);
    }
    long long ans = 0;
    for (int i = 0; i < n; i++) ans = (ans + (long long)a[i] * (i - L[i]) % MOD * (R[i] - i)) % MOD;
    return ans;
}

vector<string> topKFrequent(vector<string>& words, int k) {
