}

ListNode* reverseKGroup(ListNode* head, int k) {
    ListNode dummy(0, head); ListNode* groupPrev = &dummy;
    while (true) {
        ListNode* kth = groupPrev;
        for (int i = 0; i < k && kth; i++) kth = kth->next;   // 1. is there a full group?
        if (!kth) break;
        ListNode *groupNext = kth->next, *prev = groupNext, *cur = groupPrev->next;
        while (cur != groupNext) {                              // 2. reverse the group
            ListNode* nx = cur->next; cur->next = prev; prev = cur; cur = nx;
        }
        ListNode* first = groupPrev->next;                      // 3. reconnect
        groupPrev->next = kth; groupPrev = first;
    }
    return dummy.next;
}

