class LRUCache {
    int cap; list<pair<int,int>> L;                         // front = most recent
    unordered_map<int, list<pair<int,int>>::iterator> M;
public:
    LRUCache(int c): cap(c) {}
    int get(int k) {
        auto it = M.find(k); if (it == M.end()) return -1;
        L.splice(L.begin(), L, it->second);                  // move to front, O(1)
        return it->second->second;
    }
    void put(int k, int v) {
        if (get(k) != -1) { L.begin()->second = v; return; }
        if ((int)L.size() == cap) { M.erase(L.back().first); L.pop_back(); }
        L.emplace_front(k, v); M[k] = L.begin();
    }
};

int shortestPath(vector<vector<int>>& g) {                  // 0 = free, 1 = wall
    int R = g.size(), C = g[0].size();
    if (g[0][0] || g[R-1][C-1]) return -1;
    queue<array<int,2>> q; q.push({0,0}); g[0][0] = 1;       // mark on push
    int dr[] = {-1,1,0,0}, dc[] = {0,0,-1,1};
    for (int d = 0; !q.empty(); d++) {
        for (int s = q.size(); s > 0; s--) {                 // one layer
            auto [r, c] = q.front(); q.pop();
            if (r == R-1 && c == C-1) return d;
            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k], nc = c + dc[k];
                if (nr < 0 || nr >= R || nc < 0 || nc >= C || g[nr][nc]) continue;
                g[nr][nc] = 1; q.push({nr, nc});
            }
        }
    }
    return -1;
}

bool isBipartite(vector<vector<int>>& g) {
    int n = g.size(); vector<int> col(n, -1);
    for (int s = 0; s < n; s++) {                    // every component
        if (col[s] != -1) continue;
        queue<int> q; q.push(s); col[s] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : g[u]) {
                if (col[v] == -1) { col[v] = col[u] ^ 1; q.push(v); }
                else if (col[v] == col[u]) return false;   // same colour on one edge
            }
        }
    }
    return true;
}
