string alienOrder(const vector<string>& w) {
    vector<array<bool,26>> adj(26); vector<int> indeg(26, -1);   // -1 = letter absent
    for (auto& s : w) for (char c : s) indeg[c-'a'] = 0;
    for (int i = 0; i + 1 < (int)w.size(); i++) {
