        while (j < (int)min(a.size(), b.size()) && a[j] == b[j]) j++;
        if (j == (int)b.size() && a.size() > b.size()) return "";   // "abc" before "ab"
        if (j < (int)min(a.size(), b.size()) && !adj[a[j]-'a'][b[j]-'a']) {
            adj[a[j]-'a'][b[j]-'a'] = true; indeg[b[j]-'a']++;    // first difference only
        }
