void go(const vector<int>& a, int start, int remain) {        // Combination Sum II
    if (remain == 0) { res.push_back(path); return; }
    for (int i = start; i < (int)a.size(); i++) {
        if (i > start && a[i] == a[i-1]) continue;            // 1. same value, same depth
        if (a[i] > remain) break;                              // 2. sorted -> prune
        path.push_back(a[i]);                                  // 3. choose
        go(a, i + 1, remain - a[i]);                           // 4. explore (i+1: use once)
        path.pop_back();                                       // 5. un-choose
    }
}
