// Step 1: recursion with memo (top-down)  - House Robber
vector<int> memo;                       // -1 = unknown
int rob(const vector<int>& a, int i) {
    if (i >= (int)a.size()) return 0;   // base: nothing left
    if (memo[i] != -1) return memo[i];
    return memo[i] = max(rob(a, i + 1), a[i] + rob(a, i + 2));   // skip or take
}
// Step 2: table (bottom-up): dp[i] = max(dp[i+1], a[i] + dp[i+2]), i from n-1 down to 0
// Step 3: space: only dp[i+1], dp[i+2] are read -> two variables
int robFast(const vector<int>& a) {
    int next1 = 0, next2 = 0;           // dp[i+1], dp[i+2]
    for (int i = (int)a.size() - 1; i >= 0; i--) {
        int cur = max(next1, a[i] + next2);
        next2 = next1; next1 = cur;
    }
    return next1;
}

// Max subarray sum with at most one deletion (LC 1186)
int maximumSum(const vector<int>& a) {
    int keep = a[0];          // best sum ending at i, no deletion
    int del = INT_MIN / 2;    // best sum ending at i, one deletion used
    int best = a[0];
    for (int i = 1; i < (int)a.size(); i++) {
        del = max(del + a[i], keep);         // delete a[i] (take keep), or extend a deleted run
        keep = max(keep + a[i], a[i]);       // Kadane
        best = max({best, keep, del});
    }
    return best;
}

int minPathSum(const vector<vector<int>>& g) {
    int R = g.size(), C = g[0].size();
    vector<vector<int>> dp(R + 1, vector<int>(C + 1, INT_MAX));   // padded border = INF
    dp[0][1] = 0;                                    // lets (1,1) = g[0][0] + 0
    for (int r = 1; r <= R; r++)
        for (int c = 1; c <= C; c++)
            dp[r][c] = g[r-1][c-1] + min(dp[r-1][c], dp[r][c-1]);
    return dp[R][C];
}
