    dp[0][0] = 1;
    for (int j = 1; j <= m; j++) dp[0][j] = dp[0][j-1] && p[j-1] == '*';   // base row
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++) {
            if (p[j-1] == '*') dp[i][j] = dp[i][j-1] || dp[i-1][j];  // empty | eat one
            else dp[i][j] = dp[i-1][j-1] && (p[j-1] == '?' || p[j-1] == s[i-1]);
