int maxCoins(vector<int> a) {                     // Burst Balloons
    a.insert(a.begin(), 1); a.push_back(1);
    int n = a.size(); vector<vector<int>> dp(n, vector<int>(n, 0));
    for (int len = 2; len < n; len++)                 // open interval (l, r)
        for (int l = 0; l + len < n; l++) {
            int r = l + len;
            for (int k = l + 1; k < r; k++)           // k = LAST balloon burst in (l, r)
                dp[l][r] = max(dp[l][r], dp[l][k] + a[l] * a[k] * a[r] + dp[k][r]);
        }
    return dp[0][n-1];
}

int maxProfit(int k, const vector<int>& p) {
    vector<int> hold(k + 1, INT_MIN / 2), freeS(k + 1, 0);
    for (int x : p)
        for (int j = 1; j <= k; j++) {
            hold[j]  = max(hold[j], freeS[j-1] - x);    // buy: starts transaction j
            freeS[j] = max(freeS[j], hold[j] + x);      // sell: completes transaction j
        }
    return freeS[k];
}
