int best;                                  // record: init to INT_MIN, not 0
int gain(TreeNode* n) {                    // best downward chain from n
    if (!n) return 0;
    int l = max(0, gain(n->left));         // drop a negative branch
    int r = max(0, gain(n->right));
    best = max(best, n->val + l + r);      // path that bends at n
    return n->val + max(l, r);             // parent can extend one side only
}
int maxPathSum(TreeNode* root) { best = INT_MIN; gain(root); return best; }
// House Robber III: return {robbed, skipped}
pair<int,int> rob(TreeNode* n) {
    if (!n) return {0, 0};
    auto [lr, ls] = rob(n->left); auto [rr, rs] = rob(n->right);
    return { n->val + ls + rs, max(lr, ls) + max(rr, rs) };
}

int minNumberOfSemesters(int n, vector<vector<int>>& rel, int k) {
    vector<int> pre(n, 0);
    for (auto& r : rel) pre[r[1]-1] |= 1 << (r[0]-1);
    int full = (1 << n) - 1; vector<int> dp(1 << n, INT_MAX); dp[0] = 0;
    for (int mask = 0; mask < full; mask++) {
        if (dp[mask] == INT_MAX) continue;
        int avail = 0;
        for (int i = 0; i < n; i++)
            if (!(mask >> i & 1) && (pre[i] & mask) == pre[i]) avail |= 1 << i;
        if (__builtin_popcount(avail) <= k) { dp[mask|avail] = min(dp[mask|avail], dp[mask] + 1); continue; }
        for (int s = avail; s; s = (s - 1) & avail)          // submasks of avail
            if (__builtin_popcount(s) == k) dp[mask|s] = min(dp[mask|s], dp[mask] + 1);
    }
    return dp[full];
}

int eraseOverlapIntervals(vector<vector<int>>& v) {      // min removals = n - max kept
    sort(v.begin(), v.end(), [](auto& a, auto& b){ return a[1] < b[1]; });  // by END
    int kept = 0; long long lastEnd = LLONG_MIN;
    for (auto& x : v)
        if (x[0] >= lastEnd) { kept++; lastEnd = x[1]; }   // compatible -> take it
    return v.size() - kept;
}
int jump(const vector<int>& a) {                          // Jump Game II
    int jumps = 0, curEnd = 0, far = 0;
    for (int i = 0; i + 1 < (int)a.size(); i++) {
        far = max(far, i + a[i]);
        if (i == curEnd) { jumps++; curEnd = far; }        // level finished
    }
    return jumps;
}

struct BIT {                                     // 1-indexed Fenwick
    int n; vector<long long> t;
    BIT(int n): n(n), t(n + 1, 0) {}
    void add(int i, long long v) { for (; i <= n; i += i & -i) t[i] += v; }
    long long sum(int i) { long long s = 0; for (; i > 0; i -= i & -i) s += t[i]; return s; }
    long long range(int l, int r) { return sum(r) - sum(l - 1); }
};
struct Seg {                                     // iterative, point set + range max [l, r)
    int n; vector<int> t;
    Seg(int n): n(n), t(2 * n, INT_MIN) {}
    void set(int i, int v) { for (t[i += n] = v; i > 1; i >>= 1) t[i >> 1] = max(t[i], t[i ^ 1]); }
    int query(int l, int r) { int res = INT_MIN;
        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
            if (l & 1) res = max(res, t[l++]);
            if (r & 1) res = max(res, t[--r]); }
        return res; }
};

int pick(const vector<int>& a, int target) {          // reservoir sampling, k = 1
    int ans = -1, seen = 0;
    for (int i = 0; i < (int)a.size(); i++)
        if (a[i] == target && rand() % ++seen == 0) ans = i;   // keep with prob 1/seen
    return ans;
}
double myPow(double x, long long n) {                  // long long: n can be INT_MIN
    if (n < 0) { x = 1 / x; n = -n; }
    double r = 1;
    for (; n; n >>= 1, x *= x) if (n & 1) r *= x;
    return r;
}
int singleNumber(const vector<int>& a) { int r = 0; for (int x : a) r ^= x; return r; }
// lowest set bit: x & -x    clear it: x & (x - 1)    popcount: __builtin_popcount(x)

vector<int> lps(const string& p) {                    // KMP prefix function
    vector<int> l(p.size(), 0);
    for (int i = 1, k = 0; i < (int)p.size(); i++) {
        while (k > 0 && p[i] != p[k]) k = l[k - 1];       // fall back
        if (p[i] == p[k]) k++;
        l[i] = k;
    }
    return l;
}
// rolling hash with mod 2^61-1 or two 1e9+7-style mods
using ull = unsigned long long; const ull B = 131;
vector<ull> H, P;                                      // overflow mod 2^64 (fast, hackable)
void build(const string& s) { int n = s.size(); H.assign(n + 1, 0); P.assign(n + 1, 1);
    for (int i = 0; i < n; i++) { H[i+1] = H[i] * B + s[i]; P[i+1] = P[i] * B; } }
ull sub(int l, int r) { return H[r] - H[l] * P[r - l]; }   // s[l..r)
